from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])

    def dominant_line(vals):
        counts = Counter(vals)
        color, count = counts.most_common(1)[0]
        return color, count / len(vals)

    # Divider rows/columns have the divider color over most of their length;
    # the broad solid panel fill does not.
    row_lines = [r for r, row in enumerate(grid) if dominant_line(row)[1] >= 0.80]
    col_lines = [c for c in range(w)
                 if dominant_line([grid[r][c] for r in range(h)])[1] >= 0.80]
    if len(row_lines) < 2 or len(col_lines) < 2:
        raise ValueError("could not identify divider lattice")

    intersections = [[grid[r][c] for c in col_lines] for r in row_lines]
    sep = Counter(x for row in intersections for x in row).most_common(1)[0][0]
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]

    # Ignore only blank outer lattice lines; preserve blank internal separators.
    while len(row_lines) > 2 and all(x == sep for x in intersections[0]):
        row_lines.pop(0)
        intersections.pop(0)
    while len(row_lines) > 2 and all(x == sep for x in intersections[-1]):
        row_lines.pop()
        intersections.pop()
    while len(col_lines) > 2 and all(row[0] == sep for row in intersections):
        col_lines.pop(0)
        intersections = [row[1:] for row in intersections]
    while len(col_lines) > 2 and all(row[-1] == sep for row in intersections):
        col_lines.pop()
        intersections = [row[:-1] for row in intersections]

    out = []
    for r in range(len(intersections) - 1):
        out_row = []
        for c in range(len(intersections[0]) - 1):
            a, b = intersections[r][c], intersections[r][c + 1]
            d, e = intersections[r + 1][c], intersections[r + 1][c + 1]
            if a == b == d == e:
                out_row.append(background if a == sep else a)
            else:
                out_row.append(background)
        out.append(out_row)
    return out


def summarize_intersections(intersections, sep, background):
    """Equivalent lattice-level helper, useful for fixture validation."""
    while len(intersections) > 2 and all(x == sep for x in intersections[0]):
        intersections = intersections[1:]
    while len(intersections) > 2 and all(x == sep for x in intersections[-1]):
        intersections = intersections[:-1]
    while len(intersections[0]) > 2 and all(row[0] == sep for row in intersections):
        intersections = [row[1:] for row in intersections]
    while len(intersections[0]) > 2 and all(row[-1] == sep for row in intersections):
        intersections = [row[:-1] for row in intersections]
    return [[(background if intersections[r][c] == sep else intersections[r][c])
             if intersections[r][c] == intersections[r][c + 1] ==
                intersections[r + 1][c] == intersections[r + 1][c + 1]
             else background
             for c in range(len(intersections[0]) - 1)]
            for r in range(len(intersections) - 1)]


if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
