from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Background is the most frequent color.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            col = grid[r][c]
            if col == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == col and (ny,nx) not in seen:
                        seen.add((ny,nx)); q.append((ny,nx))
            comps.append((col, comp))
    # Find an edge-reaching L guide, preferring a large component with an elbow.
    guides = []
    for col, comp in comps:
        if not any(y in (0,h-1) or x in (0,w-1) for y,x in comp):
            continue
        for y, x in comp:
            row_cells = [(yy,xx) for yy,xx in comp if yy == y]
            col_cells = [(yy,xx) for yy,xx in comp if xx == x]
            if len(row_cells) >= 2 and len(col_cells) >= 2:
                horiz_dirs = [1 if xx > x else -1 for yy,xx in row_cells if xx != x]
                vert_dirs = [1 if yy > y else -1 for yy,xx in col_cells if yy != y]
                if horiz_dirs and vert_dirs:
                    # Guide's open quadrant points away from both arms.
                    dx = -horiz_dirs[0]
                    dy = -vert_dirs[0]
                    guides.append((len(comp), col, y, x, dy, dx))
    if not guides:
        return [row[:] for row in grid]
    _, guide_color, r, c, dy, dx = max(guides)
    # Select the nearest object in the quadrant opposite the two guide arms.
    target = None
    best = None
    for col, comp in comps:
        if col == guide_color:
            continue
        cy = sum(y for y,x in comp) / len(comp)
        cx = sum(x for y,x in comp) / len(comp)
        if (cy-r)*dy <= 0 or (cx-c)*dx <= 0:
            continue
        dist = min((y-r)**2 + (x-c)**2 for y,x in comp)
        if best is None or dist < best:
            best, target = dist, comp
    out = [row[:] for row in grid]
    if target:
        for y,x in target:
            out[y][x] = guide_color
    return out

