    for r, c in comp:
        arms = []
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            n = 0
            y, x = r + dr, c + dc
            while (y, x) in cells:
                n += 1
                y += dr
                x += dc
            arms.append((n, (dr, dc)))
        dirs = [d for n, d in arms if n]
        for i, (n1, d1) in enumerate(arms):
            for n2, d2 in arms[i + 1:]:
                if n1 and n2 and d1[0] * d2[0] + d1[1] * d2[1] == 0:
                    score = n1 + n2
                    if best is None or score > best[0]:
                        best = (score, (r, c), d1, d2)
    return best


