from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the stripe coordinate: straight rows/columns or either diagonal.
    coords = {
        "row": lambda r, c: r,
        "col": lambda r, c: c,
        "sum": lambda r, c: r + c,
        "diff": lambda r, c: c - r,
    }
    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    counts = {name: Counter(fn(r, c) for r, c, _ in points) for name, fn in coords.items()}
    # A seed stripe has many cells sharing its coordinate; pick the strongest
    # one-dimensional alignment, prioritizing horizontal/vertical then diagonals.
    priority = {"row": 0, "col": 1, "sum": 2, "diff": 3}
    axis = max(coords, key=lambda name: (max(counts[name].values(), default=0), -priority[name]))
    fn = coords[axis]
    samples = [(fn(r, c), color) for r, c, color in points]

    # Find the smallest period that assigns each observed stripe phase one color.
    period = None
    for p in range(1, max(h, w) + 1):
        phase_colors = {}
        valid = True
        for q, color in samples:
            phase = q % p
            if phase in phase_colors and phase_colors[phase] != color:
                valid = False
                break
            phase_colors[phase] = color
        if valid:
            period = p
            break
    phase_colors = {}
    for q, color in samples:
        phase_colors[q % period] = color
    fallback = Counter(color for _, color in samples).most_common(1)[0][0]
    return [[phase_colors.get(fn(r, c) % period, fallback) for c in range(w)] for r in range(h)]

