    """Return (top, left, bottom, right) of the largest all-True rectangle."""
    if not mask or not mask[0]:
        return None
    h, w = len(mask), len(mask[0])
    heights = [0] * w
    best = None
    best_area = 0
    for r in range(h):
        for c in range(w):
            heights[c] = heights[c] + 1 if mask[r][c] else 0
        stack = []
        for c in range(w + 1):
