def transform(grid):
    """Extend marker colors along paired lanes defined by equal edge bars."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    def runs(line):
        result = []
        i = 0
        while i < len(line):
            if line[i] == bg:
                i += 1
                continue
            j = i + 1
            while j < len(line) and line[j] == line[i]:
                j += 1
            if j - i >= 2:
                result.append((i, j, line[i]))
            i = j
        return result

    # Candidate paired bars on opposite edges; match equal span length and color.
    candidates = []
    for axis in ('horizontal', 'vertical'):
        if axis == 'horizontal':
            first, last = runs(grid[0]), runs(grid[-1])
        else:
            first = runs([grid[r][0] for r in range(h)])
            last = runs([grid[r][-1] for r in range(h)])
        for a, b in ((a, b) for a in first for b in last):
            if a[1] - a[0] == b[1] - b[0] and a[2] == b[2]:
                candidates.append((a[1]-a[0], axis, a, b))
    if not candidates:
        return out
    _, axis, first, last = max(candidates)
    a0, a1, bar_color = first
    b0, b1, _ = last

    if axis == 'horizontal':
        edge1, edge2 = 0, h - 1
        for r in range(1, h - 1):
            for c in range(w):
                value = grid[r][c]
                if value == bg:
                    continue
                if a0 <= c < a1:
                    offset = c - a0
                    other = b0 + offset
                    for rr in range(1, h - 1):
                        out[rr][other] = value
                    for rr in range(1, r):
                        out[rr][c] = value
                    out[r][c] = 4
                elif b0 <= c < b1:
                    offset = c - b0
                    other = a0 + offset
                    for rr in range(1, h - 1):
                        out[rr][other] = value
                    for rr in range(r + 1, h - 1):
                        out[rr][c] = value
                    out[r][c] = 4
    else:
        for r in range(h):
            for c in range(1, w - 1):
                value = grid[r][c]
                if value == bg:
                    continue
                if a0 <= r < a1:
                    offset = r - a0
                    other = b0 + offset
                    for cc in range(1, w - 1):
                        out[other][cc] = value
                    for cc in range(1, c):
                        out[r][cc] = value
                    out[r][c] = 4
                elif b0 <= r < b1:
                    offset = r - b0
                    other = a0 + offset
                    for cc in range(1, w - 1):
                        out[other][cc] = value
                    for cc in range(c + 1, w - 1):
                        out[r][cc] = value
                    out[r][c] = 4
    return out

